import unittest

from hourglass.models import Shift, Span
from hourglass.timesheet import timesheet_lines

def _shift(worker, minutes, weekday="mon"):
    """A shift from 08:00 lasting the given minutes."""
    return Shift(worker, weekday, Span(480, 480 + minutes))

class TimesheetLinesTests(unittest.TestCase):
    def test_busiest_workers_first(self):
        shifts = [_shift("Odell", 240), _shift("Ann", 480)]
        first, other = timesheet_lines(shifts)
        self.assertEqual(first, "Ann: 1 shift, 8.0 hours")
        self.assertEqual(other, "Odell: 1 shift, 4.0 hours")

    def test_shifts_counted_and_summed(self):
        shifts = [_shift("Ann", 240), _shift("Ann", 60)]
        (only,) = timesheet_lines(shifts)
        self.assertEqual(only, "Ann: 2 shifts, 5.0 hours")

    def test_ties_sorted_by_name(self):
        shifts = [_shift("Zed", 240), _shift("Ann", 240)]
        first, other = timesheet_lines(shifts)
        self.assertEqual(first, "Ann: 1 shift, 4.0 hours")
        self.assertEqual(other, "Zed: 1 shift, 4.0 hours")

    def test_hours_to_one_decimal(self):
        (only,) = timesheet_lines([_shift("Ann", 50)])
        self.assertEqual(only, "Ann: 1 shift, 0.8 hours")

    def test_empty_list_raises(self):
        with self.assertRaises(ValueError):
            timesheet_lines([])

    def test_blank_worker_raises(self):
        with self.assertRaises(ValueError):
            timesheet_lines([_shift("   ", 240)])
